/**
 * Deterministic lessons builder: the MEMORY.md analog.
 *
 * Recomputes the bounded per-repository lesson digest from authoritative
 * attempt memory. Pure and deterministic — the same state always produces the
 * same records — so the stored view can never disagree with the records it
 * summarizes. It is generated by trusted writers only and carries a source
 * digest a reader can verify by recomputing.
 */

import {
  canonicalStringify,
  canonicalStringifySha256,
} from "../contracts/canonical.ts";
import {
  MEMORY_LESSONS_BUILDER_VERSION,
  memoryLessonsIdV1,
} from "../contracts/memory-lessons.ts";
import type {
  MemoryLessonsRecordV1,
  MemoryLessonV1,
} from "../contracts/memory-lessons.ts";
import type { RepairStateSnapshotV1 } from "../contracts/state-snapshots.ts";
import { MaxItems } from "../contracts/validation.ts";
import type { RepositoryIdentityV1 } from "../contracts/shared.ts";
import {
  decideEquivalentAttemptV1,
  DEFAULT_ATTEMPT_EQUIVALENCE_POLICY_V1,
} from "./attempt-policy.ts";

function sameRepository(
  left: RepositoryIdentityV1,
  right: RepositoryIdentityV1,
): boolean {
  return left.owner === right.owner && left.name === right.name &&
    left.installationId === right.installationId;
}

/** Canonical digest of the attempt-memory records one view was built from. */
export function memoryLessonsSourceDigestV1(
  snapshot: RepairStateSnapshotV1,
): Promise<string> {
  const sorted = [...snapshot.attemptMemory].sort((left, right) =>
    left.id < right.id ? -1 : left.id > right.id ? 1 : 0
  );
  return canonicalStringifySha256({
    domain: "sentinel.memory.lessons-source.v1",
    records: sorted,
  });
}

/**
 * One deterministic lesson per recorded failure family: the count, the closed
 * failure facts and whether the loop breaker currently refuses an unchanged
 * replay. Bounded by the contract parser limits.
 */
export async function buildMemoryLessonsV1(
  snapshot: RepairStateSnapshotV1,
  now: number,
): Promise<MemoryLessonsRecordV1[]> {
  const sourceDigest = await memoryLessonsSourceDigestV1(snapshot);
  const byRepository = new Map<string, RepositoryIdentityV1>();
  for (const record of snapshot.attemptMemory) {
    const key =
      `${record.repository.owner}/${record.repository.name}#${record.repository.installationId}`;
    if (!byRepository.has(key)) byRepository.set(key, record.repository);
  }
  const lessons: MemoryLessonsRecordV1[] = [];
  for (const repository of [...byRepository.values()]) {
    const entries: MemoryLessonV1[] = [];
    for (const record of snapshot.attemptMemory) {
      if (!sameRepository(record.repository, repository)) continue;
      if (record.entries.length === 0) continue;
      let chosen = record.entries[record.entries.length - 1];
      let refused = false;
      for (const entry of record.entries) {
        const decision = decideEquivalentAttemptV1({
          record,
          fingerprint: entry.fingerprint,
          failureClass: entry.failureClass,
          now,
          policy: DEFAULT_ATTEMPT_EQUIVALENCE_POLICY_V1,
        });
        if (decision.decision === "refuse") {
          chosen = entry;
          refused = true;
          break;
        }
      }
      // A recorded success at or after this failure resolves it: the lesson
      // becomes history (how a stubborn blocker was eventually cleared)
      // instead of an open refusal.
      const resolved = record.lastSuccessAtMs !== null &&
        record.lastSuccessAtMs !== undefined &&
        record.lastSuccessAtMs >= chosen.lastAtMs;
      if (resolved) refused = false;
      // Version-control awareness: the family succeeded at an OLDER runtime
      // revision and still fails at a different (current) one.
      const successRevision = record.lastSuccessRevision ?? null;
      const successAt = record.lastSuccessAtMs ?? null;
      const regression = successRevision !== null && successAt !== null &&
        record.entries.some((entry) =>
          entry.controllerSha !== successRevision && entry.lastAtMs > successAt
        );
      entries.push({
        taskId: record.taskId,
        kind: "equivalent_failures_recorded",
        detail: chosen.detail,
        stage: chosen.stage,
        failureClass: chosen.failureClass,
        count: chosen.count,
        base: record.base,
        lastAtMs: chosen.lastAtMs,
        refused,
        resolved,
        regression,
      });
    }
    // Refused lessons first, then most recent: the reader sees what currently
    // blocks first. Deterministic tiebreak keeps the view reproducible, and
    // the contract bound is enforced here so the stored record always parses.
    // Excess summaries are dropped by design — the digest is a bounded VIEW,
    // and the authoritative attempt-memory records remain complete.
    entries.sort((left, right) => {
      if (left.refused !== right.refused) return left.refused ? -1 : 1;
      if (left.lastAtMs !== right.lastAtMs) {
        return right.lastAtMs - left.lastAtMs;
      }
      return String(left.taskId) < String(right.taskId) ? -1 : 1;
    });
    const boundedEntries = entries.slice(0, MaxItems.lessonEntries);
    const id = await memoryLessonsIdV1({
      repository,
      builderVersion: MEMORY_LESSONS_BUILDER_VERSION,
    });
    lessons.push({
      version: "v1",
      kind: "memory_lessons",
      id,
      repository,
      builderVersion: MEMORY_LESSONS_BUILDER_VERSION,
      sourceDigest,
      generatedAt: now,
      entries: boundedEntries,
    });
  }
  lessons.sort((left, right) => left.id < right.id ? -1 : 1);
  return lessons;
}

/** Stable canonical form for tests and digest comparisons. */
export function memoryLessonsCanonicalV1(
  records: readonly MemoryLessonsRecordV1[],
): string {
  return canonicalStringify(records);
}
